path1",subpath2:"subpath2"}}]},preview:"/preview",toolbar:true,imports:["vue"],components:{richTextComponents:"~/prismic/richTextComponents"}}},app:{baseURL:"/",buildId:"513e9521-44ec-4b76-a82f-bb8aaa8e0497",buildAssetsDir:"/_nuxt/",cdnURL:""}}</script><script type="application/json" data-nuxt-data="nuxt-app" data-ssr="true" id="__NUXT_DATA__">[["ShallowReactive",1],{"prerenderedAt":2,"data":3,"state":154,"once":13461,"_errors":13462,"serverRendered":160,"path":13464,"pinia":13465},1784022562111,["ShallowReactive",4],{"content-page:tax":5},{"uid":6,"document":7,"postSlices":153},"tax",{"titleTag":8,"metaDescription":9,"canonical":10,"subpath1":11,"subpath2":13,"slices":14},"Find Out More About Our Tax Policy | Evri","Find out more information on our tax governance. Evri have a responsible attitude toward risk and arranging tax affairs","tax.html\u002F\u002Fwww.evri.com\u002Ftax",{"link_type":12},"Document",{"link_type":12},[15],{"variation":16,"version":17,"items":18,"primary":20,"id":150,"slice_type":151,"slice_label":152},"default-slice","sktwi1xtmkfgx8626",[19],{},{"content":21},[22,27,35,40,43,54,59,62,65,68,73,76,79,82,85,90,93,96,99,104,107,110,113,116,119,122,127,130,133,136,139,142,144,146,148],{"type":23,"text":24,"spans":25,"direction":26},"heading2","Tax Policy",[],"ltr",{"type":28,"text":29,"spans":30,"direction":26},"paragraph","Evri Group Tax Strategy",[31],{"start":32,"end":33,"type":34},0,23,"strong",{"type":28,"text":36,"spans":37,"direction":26},"Introduction",[38],{"start":32,"end":39,"type":34},12,{"type":28,"text":41,"spans":42,"direction":26},"Evri is the UK’s biggest dedicated parcel delivery company handling 900 million parcels each year. We have 12,000 employees plus more than 20,000 self-employed couriers, with 5 national hubs, 50 regional depots, 500 local delivery units, and a network of 8,500 ParcelShops and over 3,000 lockers.",[],{"type":28,"text":44,"spans":45,"direction":26},"Evri works with a wide range of businesses in the UK from leading high street and online retailers to SMEs and micro-sellers. We also deliver for consumers through our www.evri.com website. Evri provides delivery solutions for anyone who wants to send a parcel in the UK and to more than 200 international destinations.",[46],{"start":47,"end":48,"type":49,"data":50},168,180,"hyperlink",{"link_type":51,"url":52,"target":53},"Web","tax.html\u002F\u002Fwww.evri.com","_blank",{"type":28,"text":55,"spans":56,"direction":26},"Scope",[57],{"start":32,"end":58,"type":34},5,{"type":28,"text":60,"spans":61,"direction":26},"This strategy applies to the group of companies headed by Project Edge Topco Ltd (“the UK Group”) which includes the following UK companies: Edge Midco Limited, Edge Finco Plc, Edge Bidco Limited, Concert Topco Limited, Concert Midco Limited, Concert Bidco Limited, Concert Newco Limited, Evri Limited, Evri European Logistics Limited, Evri General Services (UK) Limited and Evri Parcelnet Limited, DHL Parcel UK Holding Limited, UK Mail Group Limited, DHL eCommerce UK Limited and Coll-8 Logistics UK Limited.",[],{"type":28,"text":63,"spans":64,"direction":26},"The UK Group majority owned by Apollo Global Management Group, which is a leading independent private equity investment business, with a minority share owned by Deutsche Post DHL Group, which is a leading international logistics business.",[],{"type":28,"text":66,"spans":67,"direction":26},"The strategy has been approved by the Executive Committee of the above UK Group entities and is considered to apply from its date of publication until it is superseded. Evri regards publication of the Strategy as fulfilling its obligation under paragraph 16(2) Schedule 19 FA 2016 for the period ended 28 February 2028.",[],{"type":28,"text":69,"spans":70,"direction":26},"Commitment to compliance",[71],{"start":32,"end":72,"type":34},24,{"type":28,"text":74,"spans":75,"direction":26},"Evri aims to be a preferred choice for customers; building sustainable long-term relationships by acting fairly and, ethically with integrity, following necessary due process.",[],{"type":28,"text":77,"spans":78,"direction":26},"Evri always applies the core principles of social responsibility and sustainability to its business and considers potential reputational impacts as part of decision making.",[],{"type":28,"text":80,"spans":81,"direction":26},"Whilst the UK Group has a responsibility to deliver returns and value for its shareholders, the Group takes the requirements of all stakeholders into account and is committed to complying with UK tax rules and regulations and to paying the right amount of tax at the right time.",[],{"type":28,"text":83,"spans":84,"direction":26},"Apollo and DHL expect their investments to aim for strict adherence to local tax legislation and Evri maintains this commitment.",[],{"type":28,"text":86,"spans":87,"direction":26},"Tax governance",[88],{"start":32,"end":89,"type":34},14,{"type":28,"text":91,"spans":92,"direction":26},"The CFO of Evri Ltd (“CFO”) has assumed responsibility and ownership of the tax strategy for all tax matters, for all Group companies, with day-to-day management resting with the Head of Tax of Evri Ltd. The CFO is also appointed as Senior Accounting Officer (“SAO”) with responsibility for monitoring the integrity of the respective financial reporting systems, internal controls and risk management frameworks which includes those elements relating to taxation.",[],{"type":28,"text":94,"spans":95,"direction":26},"Processes relating to specific UK taxes are allocated to appropriate internal specialists who maintain monitoring of systems and activities to identify and mitigate risks. Changes to business activity and in legislation are considered for impact on existing systems, processes and reporting, with required consequential changes made to address risks based on materiality and relevant obligations.",[],{"type":28,"text":97,"spans":98,"direction":26},"The UK Group is also required to report to and consult with the shareholders regarding material issues affecting the structure or operation of the UK businesses from a tax perspective, including identification of significant tax risks.",[],{"type":28,"text":100,"spans":101,"direction":26},"Responsible attitude toward risk and arranging our tax affairs",[102],{"start":32,"end":103,"type":34},62,{"type":28,"text":105,"spans":106,"direction":26},"The UK Group seeks to actively identify, evaluate, monitor and manage tax risk associated with our business activities.",[],{"type":28,"text":108,"spans":109,"direction":26},"The UK Group aims for certainty on the tax positions adopted and, to adhere to our principles, any structuring undertaken will have commercial and economic substance.",[],{"type":28,"text":111,"spans":112,"direction":26},"The UK Group will take advantage of available tax incentives, reliefs and exemptions in line with, and in the spirit of, the tax legislation.",[],{"type":28,"text":114,"spans":115,"direction":26},"The UK Group will not enter into transactions which it considers are contrived, artificial or counter the spirit of the law or whose main purpose is to create an abusive tax result.",[],{"type":28,"text":117,"spans":118,"direction":26},"UK tax law is complex and constantly evolving meaning that the correct position can sometimes be unclear. We aim to resolve these uncertainties through discussion with HM Revenue & Customs wherever possible.",[],{"type":28,"text":120,"spans":121,"direction":26},"Where there is significant uncertainty, complexity or material amounts in question, in order to address identified risks, we may seek external advice from reputable tax advisors, legal firms or tax counsel as appropriate and will follow necessary due process.",[],{"type":28,"text":123,"spans":124,"direction":26},"Relationship with HMRC",[125],{"start":32,"end":126,"type":34},22,{"type":28,"text":128,"spans":129,"direction":26},"The UK Group is committed to the principles of integrity, transparency and openness and seeks to apply these in its dealings with UK tax authorities. Wherever possible we seek constructive and early discussions on any new arising tax matter to obtain certainty.",[],{"type":28,"text":131,"spans":132,"direction":26},"The UK Group is committed to paying its UK taxes in full and on time and provide any relevant information requested by the tax authorities.",[],{"type":28,"text":134,"spans":135,"direction":26}," ",[],{"type":28,"text":137,"spans":138,"direction":26},"Dated: 28 February 2026",[],{"type":28,"text":140,"spans":141,"direction":26},"",[],{"type":28,"text":134,"spans":143,"direction":26},[],{"type":28,"text":140,"spans":145,"direction":26},[],{"type":28,"text":134,"spans":147,"direction":26},[],{"type":28,"text":134,"spans":149,"direction":26},[],"rich_text$1f78d35b-1a83-4435-9ddc-9febfea1a2e7","rich_text",null,[15],["Reactive",155],{"$sglobal-feature-switches":156,"$sclients":224,"$sglobal-basket-count":152},{"abtasty":157,"accessibe":161,"appPromoBanner":164,"autoDivertUpdates":168,"awin":171,"bulkInternational":174,"bulkSendEnabled":177,"businessAccountForm75Enabled":180,"enableBasketCount":183,"enableBulkPhaseTwo":186,"euCustomsDuty":189,"groovyAdvert":192,"newInternationalSendFlow":195,"newinternationalpages":202,"oohPreferenceFlag":206,"opentel":209,"premium":212,"savedCards":215,"smallParcelSize":218,"yourPricesDrawer":221},{"_createdAt":158,"_updatedAt":159,"enabled":160},"2025-11-05T15:39:37.217Z","2025-11-05T15:39:37.452Z",true,{"_createdAt":162,"_updatedAt":163,"enabled":160},"2025-07-15T08:41:16.873Z","2025-10-28T11:52:03.675Z",{"_createdAt":165,"_updatedAt":166,"enabled":167},"2026-03-06T12:16:35.816Z","2026-03-06T12:16:36.662Z",false,{"_createdAt":169,"_updatedAt":170,"enabled":167},"2026-04-30T13:26:45.107Z","2026-04-30T13:26:45.355Z",{"_createdAt":172,"_updatedAt":173,"enabled":167},"2025-08-19T09:46:14.552Z","2025-09-02T10:23:26.022Z",{"_createdAt":175,"_updatedAt":176,"enabled":160},"2025-06-23T14:37:21.102Z","2026-01-2